SERIAL=SERIES+[['英语 series + -al；参照拉丁语 serialis','系列的、依次排列的']]
INS=S+[['拉丁语 in- + serere → inserere / insertus','接入、植入、插入']]
ASSERT=S+[['拉丁语 ad- + serere → asserere / assertus','提出权属主张；断言、维护']]
ASSERTIVE=ASSERT+[['两种分析：中世纪拉丁语 assertivus；英语 assert + -ive','宣称的、坚定表达的'],['英语 assertive','敢于表达立场和需要的']]
EXERT=S+[['拉丁语 ex- + serere → exserere / exsertus','伸出去、推出来'],['英语 exert','施加、运用力量或影响']]
DES=S+[['拉丁语 de- + serere → deserere / desertus','解除联系 → 离弃、抛下']]
DESERT=DES+[['拉丁语 desertum → 古法语 desert → 英语 desert 名词','被遗弃之地 → 荒野、沙漠']]
DISS=S+[['拉丁语 dis- + serere → disserere','分开整理、逐项讨论'],['拉丁语 dissertare / dissertatio','反复论述、讨论；论述本身']]
