progress['batches']=list(dict.fromkeys(progress['batches']+['batch200_st_04']))
progress.update(next_root_index=9,next_root_id=ASSIGN['roots'][9]['id'],status='writing',active_script=None,active_written_words=0,active_note='st04 cruc27 + ba33 + ser28 completed and self-audited; next erg/org/urg, homin, mill.')
